use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // Contract (requires len(question) <= 512) is guaranteed of every input,
        // so we read `ctx.question` as given without re-checking it here.

        let system = "You are a customer support agent. Answer the customer's \
                      question using only the knowledge provided and the \
                      knowledge base. You may request the `lookup` tool to \
                      search the knowledge base; when you have enough \
                      information, answer in plain text.";

        let mut prompt = String::new();
        prompt.push_str("Intent: ");
        prompt.push_str(intent_label(ctx.intent));
        prompt.push_str("\nQuestion: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Bounded tool-orchestration loop. The only tool in this node's world
        // is the knowledge-base lookup; any other requested tool is out of
        // scope and yields no results rather than an attempt to invoke it.
        const MAX_ROUNDS: u32 = 8;
        let mut round: u32 = 0;

        loop {
            match tool_llm::generate(system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    round += 1;
                    if round > MAX_ROUNDS {
                        return ResponseResult::Error(LlmError {
                            message: "tool-orchestration loop did not converge"
                                .to_string(),
                        });
                    }

                    let results = if req.tool == "lookup" {
                        kb_read::lookup(&req.query)
                    } else {
                        Vec::new()
                    };

                    prompt.push_str("\nTool `");
                    prompt.push_str(&req.tool);
                    prompt.push_str("` results for query \"");
                    prompt.push_str(&req.query);
                    prompt.push_str("\":\n");
                    if results.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for r in &results {
                            prompt.push_str("- ");
                            prompt.push_str(r);
                            prompt.push('\n');
                        }
                    }
                }
            }
        }
    }
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

export!(Node);
```

